local module = {}
module.__index = module

function module.new(cmd, key, ...)
    local self = {}
    setmetatable(self, module)

    self.Command = cmd
    if typeof(key) == "table" then
        local t = {}
        for _, v in pairs(key) do
            table.insert(t, v.Name)
        end
        self.Key = table.concat(t, "+")
    else
        self.Key = key.Name
    end
    
    self.Args = {...}

    self._then = nil

    return self
end

function module:Named(name)
    self.Name = name
    return self
end

function module:Then(func)
    self._then = func
    return self
end

function module:Catch(func)
    self._catch = func
    return self
end


function module:SetIcon(iconOrTable)
    if typeof(iconOrTable) == "table" then
        self.Icon = iconOrTable
    else
        self.Icon = {iconOrTable}
    end
    return self
end

function module:_setIconShow(show, force)
    if not self.Icon then return end
    if typeof(self.Icon) == "table" then
        for i, v in pairs(self.Icon) do
            if not force then
                if show and i == 1 then
                    v.Visible = true
                else
                    v.Visible = false
                end
            else
                v.Visible = show
            end
        end
    else
        self.Icon.Visible = show
    end
end

function module:Execute()
    local command = self.Command
    local args = self.Args
    if typeof(args[1]) == "function" then
        args = table.pack(args[1]())
    end

    local res, err = command:CanExecute(table.unpack(args))
    if res then
        local execRes = table.pack(command:Execute(table.unpack(args)))
        if self._then then
            self._then(table.unpack(execRes))
        end
    elseif self._catch then
        self._catch(err)
    end
end

return module